"""Helpers that keep scanners honest and free of framework-induced noise.

The biggest source of false positives across the scanners is testing
parameters that are NOT user-controlled: Next.js Server Action bookkeeping
fields ($ACTION_REF_1, $ACTION_KEY, ...), ASP.NET view state, CSRF tokens,
auto-generated honeypot fields, etc. This module marks those so every
scanner can skip them before sending a single request.
"""
import secrets

# Framework-internal / non-user-controlled form field names (lowercased).
# These are auto-generated by the framework and reflect nothing the attacker
# controls in a meaningful input context.
FRAMEWORK_INTERNAL_NAMES = frozenset(
    {
        "__viewstate",
        "__viewstateencrypted",
        "__eventvalidation",
        "__eventtarget",
        "__requestverificationtoken",
        "__requestverificationtoken_input",
        "__dopostback",
        "__callback",
        "__callbackid",
        "__callbacksource",
        "_csrf",
        "csrf_token",
        "csrfmiddlewaretoken",
        "authenticity_token",
        "_token",
        "__token",
        "form_token",
        "honeypot",
        "hp",
        "_method",
        "_wpnonce",
        "nonce",
        "recaptcha_token",
        "captcha",
    }
)

# Characters frameworks use to prefix their internal fields.
_INTERNAL_PREFIX_CHARS = ("$", "_", "*", "(")


def is_user_parameter(name):
    """Return True only when a form field looks like a real user input.

    Skips:
      - empty / missing names
      - exact framework token names (__VIEWSTATE, _csrf, ...)
      - framework-prefixed names ($ACTION_REF_1, $ACTION_KEY, _token, ...)
      - names that are not slug-like (spaces, odd punctuation, '1:0' style)
    """
    if not name:
        return False
    if not isinstance(name, str):
        return False
    low = name.strip().lower()
    if not low:
        return False
    if low in FRAMEWORK_INTERNAL_NAMES:
        return False
    if low.startswith(_INTERNAL_PREFIX_CHARS):
        return False
    # Next.js / React action reference-style names: '$ACTION_1:0', '$ACTION_REF_1', ...
    if low.startswith("$action") or "action_ref" in low or "action_key" in low:
        return False
    # Slug-like sanity check: letters, digits, '-', '_' (edge-case names like
    # 'q', 'search[term]', 'email', 'user_name' are fine).
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789_-.[]")
    if not all(c in allowed for c in low):
        return False
    return True


def unique_probe(prefix="wc"):
    """Return a short random probe that cannot exist in any baseline page."""
    return f"{prefix}_{secrets.token_hex(6)}"